'use strict';
const $=id=>document.getElementById(id);
const fmt=new Intl.NumberFormat('es-ES',{useGrouping:'always',minimumFractionDigits:2,maximumFractionDigits:2});
const fmt0=new Intl.NumberFormat('es-ES',{useGrouping:'always',maximumFractionDigits:0});
const money=n=>fmt.format(n)+' USD', signed=n=>(n>=0?'+':'−')+fmt.format(Math.abs(n)), qty=n=>n.toLocaleString('es-ES',{minimumFractionDigits:3,maximumFractionDigits:3})+' BTC';
const end=Date.UTC(2026,10,20,10,42), seed=5000;
const when=(t,short=false)=>{const d=new Date(end+t*60000),day=d.getUTCDate()+' '+['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'][d.getUTCMonth()],time=String(d.getUTCHours()).padStart(2,'0')+':'+String(d.getUTCMinutes()).padStart(2,'0');return short?time:day+' · '+time};
const cycles=[
 {id:'G-17',range:'R-08',t:-90,buy:60000,q:.010,target:60600,fee:.60},
 {id:'G-15',range:'R-08',t:-204,buy:59400,q:.010,target:60000,fee:.59,sold:-108,sell:60000,sellFee:.60},
 {id:'G-12',range:'R-07',t:-976,buy:60500,q:.008,target:61105,fee:.48},
 {id:'G-10',range:'R-06',t:-7240,buy:58000,q:.025,target:58700,fee:1.45,sold:-5010,sell:58700,sellFee:1.47},
 {id:'G-06',range:'R-05',t:-18450,buy:55750,q:.020,target:56480,fee:1.12,sold:-15870,sell:56480,sellFee:1.13},
 {id:'G-03',range:'R-04',t:-37940,buy:54100,q:.018,target:54700,fee:.97,sold:-36190,sell:54700,sellFee:.98}
];
const net=c=>(c.sell-c.buy)*c.q-c.fee-c.sellFee;
const openCycles=cycles.filter(c=>c.sold==null);
const closedCycles=cycles.filter(c=>c.sold!=null);
const dayNet=closedCycles.filter(c=>when(c.sold).split(' · ')[0]===when(0).split(' · ')[0]).reduce((v,c)=>v+net(c),0);
const anchors=[[-43200,54912],[-40440,55352],[-33410,53520],[-28030,57350],[-23200,56180],[-20550,58280],[-12880,57600],[-10080,57934],[-8400,56780],[-3890,59325],[-2740,58839],[-1440,59135.2],[-1290,59280],[-1150,59170],[-810,60120],[-610,60380],[-490,59780],[-310,60020],[-163,59490],[-48,60280],[0,60384.80]];
for(const c of cycles){anchors.push([c.t,c.buy]);if(c.sold!=null)anchors.push([c.sold,c.sell])}
anchors.sort((a,b)=>a[0]-b[0]);
const prices=new Float64Array(43201);
for(let k=1;k<anchors.length;k++){
 const [t0,p0]=anchors[k-1],[t1,p1]=anchors[k],length=t1-t0;
 for(let t=t0;t<=t1;t++){
  const f=(t-t0)/length,amp=Math.min(310,32+length*.14);
  const noise=Math.sin((t-t0)*.021+k)*.64+Math.sin(t*.083)*.29+Math.cos(t*.247)*.15;
  prices[43200+t]=p0+(p1-p0)*f+Math.sin(Math.PI*f)*noise*amp;
 }
}
const price=t=>prices[43200+t];
function account(t){
 let cash=seed,btc=0,realized=0;
 for(const c of cycles){if(c.t>t)continue;cash-=c.q*c.buy+c.fee;btc+=c.q;if(c.sold!=null&&c.sold<=t){cash+=c.q*c.sell-c.sellFee;btc-=c.q;realized+=net(c)}}
 const position=btc*price(t);return {cash,position,realized,total:cash+position}
}
const now=account(0);
