let level='basic',chosen='GRID_CONTINUO',cost='base',amaAsset='BTC';
const oldHome=home,oldScreen=currentScreen;
const labels={GRID_CONTINUO:'Grid continuo',GRID_ADAPTATIVO:'Grid adaptativo',HIBRIDO:'Grid + swing',AMA:'AMA'};
function researchChart(rows){
 const values=rows.map(r=>+r[1]),min=Math.min(...values),max=Math.max(...values),span=max-min||1;
 const coords=values.map((v,i)=>[8+i/(values.length-1)*604,18+(max-v)/span*154]);
 const path=coords.map(([x,y],i)=>(i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)).join(' ');
 return '<figure><svg viewBox="0 0 680 205" class="svgplot" role="img" aria-label="Evolución histórica del patrimonio en USDT"><path d="M8 18H612M8 95H612M8 172H612" stroke="#304155" stroke-dasharray="3 5"/><path d="'+path+'" fill="none" stroke="'+(values.at(-1)>=values[0]?'#45daa2':'#ff7182')+'" stroke-width="2.4"/><text x="620" y="22">'+fmt0.format(max)+'</text><text x="620" y="172">'+fmt0.format(min)+'</text><text x="8" y="198">'+rows[0][0].slice(0,10)+'</text><text x="490" y="198">'+rows.at(-1)[0].slice(0,10)+'</text></svg><figcaption class="section-label">Patrimonio · USDT · UTC</figcaption></figure>'
}
function simulations(){
 const isAma=chosen==='AMA',fee=cost==='base'?.09:.15;
 const result=isAma?research.ama[amaAsset]:research.grid.find(r=>r.strategy===chosen&&r.cost_fee_pct_each_side===fee);
 const rows=isAma?result.history:research.daily.filter(r=>r.policy===chosen&&+r.fee_pct===fee).map(r=>[r.date_utc,+r.equity_liquidation_usdt]);
 const pnl=isAma?result.pnl:result.net_pnl_usdt,total=isAma?result.total:result.final_capital_usdt;
 const settings=group('Simulación',Object.entries(labels).map(([k,l])=>tab(l,'research:'+k,chosen===k)).join(''));
 const controls=isAma?group('Activo AMA',['BTC','ETH'].map(k=>tab(k,'asset:'+k,amaAsset===k)).join('')):group('Costes',tab('Base','cost:base',cost==='base')+tab('Estrés','cost:stress',cost==='stress'));
 const intro=isAma?'Replay del código AMA · 1 jul–18 nov 2026 · Binance '+amaAsset+'USDT · velas cerradas 1h':'Backtest de investigación · 1 ago–18 nov 2026 · Binance USDT';
 const detail=isAma?'<div class="warn">El replay utiliza capital fijo de 10.000, sin comisiones ni deslizamiento. La selección de tramos depende del índice de vela. Acumula compras y mantiene las posiciones abiertas.</div>':'<p>Capital inicial 10.000 USDT. Costes por lado '+result.cost_fee_pct_each_side+' % de comisión y '+result.cost_slippage_pct_each_side+' % de deslizamiento. Fills hipotéticos sobre velas de 5 minutos.</p>';
 let trades=isAma?result.events.map(e=>[e.timestampSimulated.slice(0,16),money(e.price).replace('USD','USDT'),fmt.format(e.amountUsd)+' USDT','Compra']):research.trades.filter(r=>r.policy===chosen&&+r.fee_pct===fee).map(r=>[r.entry_utc.slice(0,16),fmt.format(+r.entry_fill)+' → '+fmt.format(+r.exit_fill),signed(+r.net_pnl_usdt)+' USDT',r.reason]);
 return title(mobile?'Panel del bot':'Centro de control',level==='basic'?'Básico · Simulaciones':'Pro · Simulaciones')+settings+'<section class="card"><div class="cap"><h2>'+labels[chosen]+(isAma?' · '+amaAsset:'')+'</h2>'+controls+'</div><p>'+intro+'</p><div class="big">'+fmt.format(total)+' <em>USDT</em></div><div class="change"><strong class="'+(pnl>=0?'up':'down')+'">'+signed(pnl)+' USDT</strong><span>Variación del patrimonio desde 10.000 USDT</span></div>'+researchChart(rows)+'</section><div class="stats">'+stat(isAma?'Compras':'Ventas',isAma?result.totalTranchesExecuted:result.positions_closed,isAma?'Posiciones abiertas':'Ciclos cerrados')+stat('Caída máxima',fmt.format(isAma?result.drawdown:result.drawdown_intraday_liq_pct)+' %',isAma?'Julio–noviembre':'Patrimonio liquidable','down')+stat('Capital inicial','10.000','USDT')+'</div><section class="card"><h2>Cómo se obtuvo</h2><p><a href="https://drive.google.com/file/d/1mabq79pmGblzj5PACEXy-5Yn4AQUTZT_/view">Velas originales verificadas</a> · <a href="https://drive.google.com/file/d/1S--xzVf8yLtrBUivu0NYicWMnb5WpnbK/view">Resultados Grid y metodología</a> · <a href="https://github.com/luisdepargabitcon/Kraken-Autotrade/blob/47d79db3f7065e0e54481447129f2f88e9225fe2/server/services/ama/amaReplayService.ts">Código AMA ejecutado offline</a></p>'+detail+(isAma?'<p>6 compras por activo. Patrimonio = efectivo restante + cantidad acumulada × último cierre. Cada activo se ensaya con su propio capital. Gráfica desde agosto, replay iniciado en julio.</p>':'<p>Este estudio compara tres políticas Grid de investigación. Sus resultados describen la ventana histórica utilizada.</p>')+'</section>'+(level==='pro'?'<section class="card"><h2>'+ (isAma?'Compras AMA':'Operaciones de la simulación')+'</h2><div class="table-wrap"><table><thead><tr><th>Fecha UTC</th><th>Precio</th><th>'+(isAma?'Importe':'Neto')+'</th><th>Acción</th></tr></thead><tbody>'+trades.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></section>':'')+'<div class="actions">'+txtLink('Motores','nav:Motores')+txtLink('Explorar maqueta de operaciones','demo')+'</div>'
}
home=simulations;
currentScreen=function(){if(!locked&&(sub==='engine'||sub==='cycle')&&item==='AMA'){chosen='AMA';return back()+simulations()}if(!locked&&sub==='demo')return back()+oldHome();return oldScreen()};
const originalAct=act;
act=function(a){const [k,v]=a.split(':');if(['level','research','asset','cost'].includes(k)){if(k==='level')level=v;if(k==='research')chosen=v;if(k==='asset')amaAsset=v;if(k==='cost')cost=v;render();return}originalAct(a)};
const originalRender=render;
render=function(){originalRender();$('device').classList.add(level);let bar=$('experience');if(!bar){bar=document.createElement('div');bar.id='experience';document.querySelector('header').appendChild(bar)}bar.innerHTML='<span>Experiencia</span>'+group('Experiencia',tab('Básico','level:basic',level==='basic')+tab('Pro','level:pro',level==='pro'));document.querySelector('.env').innerHTML='<i></i>Simulaciones';};
render();
